431	func cmdCircuitCompile(f *cliFlags) int {
432		if ok, code := requireNameVersion("circuit-compile", f); !ok {
433			return code
434		}
435		store, code := openStore(f)
436		if store == nil {
437			return code
438		}
439		defer store.Close()
440	
441		artifact, err := store.CompileCircuit(f.name, f.version)
442		if err != nil {
443			return reportStoreError(err)
444		}
445		fmt.Printf("artifact: name=%s version=%d modulus=%d constraints=%d hash=%s\n",
446			artifact.Name, artifact.Version, artifact.Modulus, artifact.Constraints, artifact.Hash)
447		return exitOK
448	}
